import{_ as t,b as o,c as l,g as r}from"./chunks/framework.86O3EbG5.js";const p=JSON.parse('{"title":"强化学习","description":"","frontmatter":{"title":"强化学习","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/22.md","filePath":"articles/ai/books/ai-modern-approach/22.md"}'),s={name:"articles/ai/books/ai-modern-approach/22.md"};function n(a,i,e,g,d,_){return o(),l("div",null,[...i[0]||(i[0]=[r('<p>第 22 章介绍强化学习，核心是让智能体通过与环境交互、获得奖励信号来学习最优策略。重点包括：</p><h2 id="基本概念" tabindex="-1">基本概念</h2><ul><li><strong>智能体、环境、状态、动作、奖励</strong></li><li><strong>策略 π(a|s)</strong>：状态到动作的映射</li><li><strong>价值函数 V(s)</strong> 和 <strong>动作价值函数 Q(s,a)</strong></li><li><strong>折扣因子 γ</strong>：平衡即时奖励与未来奖励</li></ul><h2 id="动态规划方法" tabindex="-1">动态规划方法</h2><ul><li><strong>策略评估</strong>：给定策略计算价值函数</li><li><strong>策略迭代</strong>与<strong>值迭代</strong>：交替评估和改进策略</li><li>需要已知环境模型（转移概率和奖励）</li></ul><h2 id="无模型方法" tabindex="-1">无模型方法</h2><ul><li><strong>蒙特卡洛（MC）</strong>：基于完整回合的回报估计价值</li><li><strong>时序差分（TD）</strong>：单步自举更新，TD(0) 更新公式</li><li><strong>SARSA</strong>（on-policy）vs <strong>Q-learning</strong>（off-policy）</li></ul><h2 id="探索与利用" tabindex="-1">探索与利用</h2><ul><li><strong>ε-greedy 策略</strong>：以 ε 概率随机探索，1-ε 概率选择最优动作</li><li><strong>多臂赌博机</strong>：探索-利用权衡的经典问题</li><li>在风险敏感场景（如医疗）中需要更保守的探索策略</li></ul><h2 id="函数逼近与深度强化学习" tabindex="-1">函数逼近与深度强化学习</h2><ul><li><strong>深度 Q 网络（DQN）</strong>：经验回放、目标网络两个关键技巧</li><li><strong>策略梯度</strong>：REINFORCE 算法、基线（baseline）减少方差</li><li>连续动作空间适合策略梯度方法（如 PPO）</li></ul><h2 id="应用场景" tabindex="-1">应用场景</h2><ul><li>游戏（Atari）、机器人控制、自动驾驶决策</li><li>离线策略评估利用历史数据减少在线探索代价</li></ul>',13)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
